seen=set(); comps=[]
from collections import deque
for y in range(len(test)):
 for x in range(len(test[0])):
  if test[y][x]!=1 or (y,x) in seen: continue
  q=deque([(y,x)]);seen.add((y,x)); c=[]
  while q:
   yy,xx=q.popleft();c.append((yy,xx))
   for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
    ny,nx=yy+dy,xx+dx
    if 0<=ny<len(test) and 0<=nx<len(test[0]) and test[ny][nx]==1 and (ny,nx) not in seen:seen.add((ny,nx));q.append((ny,nx))
  comps.append(c)
print([(len(c),min(y for y,x in c),max(y for y,x in c),min(x for y,x in c),max(x for y,x in c)) for c in comps])

